    bronze_escapementlever = { name = "Bronast uhopna ročica", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast uhopna ročica za ure." },
    silver_escapementlever = { name = "Srebrn uhopna ročica", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn uhopna ročica za ure." },
    gilded_escapementlever = { name = "Pozlačen uhopna ročica", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen uhopna ročica za ure." },
